using Kaizen.Infrastructure.Persistence;
using Kaizen.Domain.Entities;
using Kaizen.Web.ViewModels;
using Microsoft.EntityFrameworkCore;
namespace Kaizen.Web.Services;

public class ReviewService(ApplicationDbContext db, ScheduleService schedule)
{
    public async Task<KaizenReviewFormViewModel?> BuildAsync(int goalId, DateOnly today, CancellationToken ct = default)
    {
        var goal = await db.Metas.AsNoTracking().Include(x => x.Acciones).SingleOrDefaultAsync(x => x.Id == goalId && x.Estado == EstadoMeta.Activa, ct); if (goal is null) return null; var previous = await db.RevisionesKaizen.AsNoTracking().Where(x => x.MetaId == goalId).OrderByDescending(x => x.FinPeriodo).FirstOrDefaultAsync(ct); var start = previous?.FinPeriodo.AddDays(1) ?? goal.FechaInicio; if (start > today) return null; var rows = await db.AccionesProgramadas.AsNoTracking().Where(x => x.AccionPlanificada!.MetaId == goalId && x.FechaProgramada >= start && x.FechaProgramada <= today).Select(x => new { x.AccionPlanificadaId, x.AccionPlanificada!.SerieAccionId, x.AccionPlanificada.Nombre, x.AccionPlanificada.CantidadObjetivo, x.AccionPlanificada.UnidadMetrica, x.FechaProgramada, x.Estado, Actual = x.Registro != null ? x.Registro.ValorReal : null, Nota = x.Registro != null ? x.Registro.Nota : null }).ToListAsync(ct); var results = rows.GroupBy(x => x.SerieAccionId).Select(g => new ReviewActionResultViewModel { AccionPlanificadaId = g.OrderByDescending(x => x.AccionPlanificadaId).First().AccionPlanificadaId, Nombre = g.Last().Nombre, Planned = g.Count(), Completed = g.Count(x => x.Estado == EstadoCumplimiento.Completada), Missed = g.Count(x => x.Estado == EstadoCumplimiento.NoRealizada), Pending = g.Count(x => x.Estado == EstadoCumplimiento.Pendiente), ExpectedTotal = g.Where(x => x.CantidadObjetivo.HasValue).Sum(x => x.CantidadObjetivo), ActualTotal = g.Where(x => x.Actual.HasValue).Sum(x => x.Actual), Unit = g.Select(x => x.UnidadMetrica).FirstOrDefault(x => !string.IsNullOrWhiteSpace(x)) }).ToList(); var active = goal.Acciones.Where(x => x.Estado == EstadoAccion.Activa && !x.VigenteHasta.HasValue).ToList(); var next = goal.FrecuenciaRevision == FrecuenciaRevision.Semanal ? today.AddDays(7) : today.AddMonths(1); return new() { MetaId = goal.Id, GoalTitle = goal.Titulo, InicioPeriodo = start, FinPeriodo = today, PlannedReviewDate = goal.FechaProximaRevision ?? today, IsEarly = goal.FechaProximaRevision > today, EstadoMetaInicial = previous?.EstadoMetaFinal ?? goal.Estado, EstadoMetaFinal = goal.Estado, Planned = rows.Count, Completed = rows.Count(x => x.Estado == EstadoCumplimiento.Completada), Missed = rows.Count(x => x.Estado == EstadoCumplimiento.NoRealizada), Pending = rows.Count(x => x.Estado == EstadoCumplimiento.Pendiente), PreviousPercentage = previous?.PorcentajeCumplimiento, BestAction = results.Where(x => x.Planned > 0).OrderByDescending(x => x.Percentage).FirstOrDefault()?.Nombre, DifficultAction = results.Where(x => x.Planned > 0).OrderBy(x => x.Percentage).FirstOrDefault()?.Nombre, MostMissedDays = string.Join(", ", rows.Where(x => x.Estado == EstadoCumplimiento.NoRealizada).GroupBy(x => x.FechaProgramada).OrderByDescending(x => x.Count()).Take(3).Select(x => $"{x.Key:dd/MM} ({x.Count()})")), Notes = rows.Select(x => x.Nota).Where(x => !string.IsNullOrWhiteSpace(x)).Cast<string>().ToList(), ActionResults = results, Decisions = active.Select(x => new ReviewDecisionViewModel { AccionPlanificadaId = x.Id, ActionName = x.Nombre, CurrentVersion = x.Version, CurrentConfiguration = Describe(x), Tipo = TipoAjuste.Mantener, FechaVigencia = today.AddDays(1), NewName = x.Nombre, NewFrequency = x.Frecuencia, NewWeekdays = x.DiasSemana, NewTime = x.Hora, NewTargetAmount = x.CantidadObjetivo, NewMetricUnit = x.UnidadMetrica, NewEndDate = x.FechaFin }).ToList() };
    }
    public async Task<int> SaveAsync(KaizenReviewFormViewModel vm, CancellationToken ct)
    {
        await using var tx = await db.Database.BeginTransactionAsync(ct); if (await db.RevisionesKaizen.AnyAsync(x => x.MetaId == vm.MetaId && x.InicioPeriodo == vm.InicioPeriodo && x.FinPeriodo == vm.FinPeriodo, ct)) throw new InvalidOperationException("Ya existe una revisión para este período."); var goal = await db.Metas.Include(x => x.Acciones).SingleAsync(x => x.Id == vm.MetaId && x.Estado == EstadoMeta.Activa, ct); var review = new RevisionKaizen { MetaId = goal.Id, InicioPeriodo = vm.InicioPeriodo, FinPeriodo = vm.FinPeriodo, PorcentajeCumplimiento = vm.PorcentajeCumplimiento, QueFunciono = vm.QueFunciono.Trim(), QueDificulto = vm.QueDificulto.Trim(), AjustePequeno = vm.CambioProximoPeriodo.Trim(), Aprendizaje = vm.Aprendizaje.Trim(), CambioProximoPeriodo = vm.CambioProximoPeriodo.Trim(), NotasAdicionales = vm.NotasAdicionales?.Trim(), EstadoMetaInicial = vm.EstadoMetaInicial, EstadoMetaFinal = goal.Estado, FechaProximaRevision = goal.FrecuenciaRevision == FrecuenciaRevision.Semanal ? vm.FinPeriodo.AddDays(7) : vm.FinPeriodo.AddMonths(1), SugerenciaAutomatica = KaizenRules.GetSuggestion(vm.PorcentajeCumplimiento) }; db.RevisionesKaizen.Add(review); await db.SaveChangesAsync(ct);
        foreach (var decision in vm.Decisions) { var current = goal.Acciones.SingleOrDefault(x => x.Id == decision.AccionPlanificadaId && x.Estado == EstadoAccion.Activa && !x.VigenteHasta.HasValue) ?? throw new InvalidOperationException("La versión de la acción ya cambió."); var old = Describe(current); AccionPlanificada? next = null; if (decision.Tipo != TipoAjuste.Mantener) { var future = await db.AccionesProgramadas.Include(x => x.Registro).Where(x => x.AccionPlanificadaId == current.Id && x.FechaProgramada >= decision.FechaVigencia && x.Estado == EstadoCumplimiento.Pendiente && x.Registro == null).ToListAsync(ct); db.AccionesProgramadas.RemoveRange(future); current.VigenteHasta = decision.FechaVigencia.AddDays(-1); current.FechaFin = current.FechaFin is null || current.FechaFin >= decision.FechaVigencia ? decision.FechaVigencia.AddDays(-1) : current.FechaFin; current.MotivoCambio = decision.Motivo; if (decision.Tipo == TipoAjuste.Pausar) current.Estado = EstadoAccion.Pausada; else if (decision.Tipo == TipoAjuste.Completar) current.Estado = EstadoAccion.Completada; else { current.Estado = EstadoAccion.Completada; next = new AccionPlanificada { MetaId = goal.Id, Nombre = decision.Tipo == TipoAjuste.Reemplazar ? decision.NewName!.Trim() : current.Nombre, Descripcion = current.Descripcion, Frecuencia = decision.NewFrequency, DiasSemana = decision.NewWeekdays, Hora = decision.NewTime, FechaInicio = decision.FechaVigencia, FechaFin = decision.NewEndDate, DificultadEstimada = current.DificultadEstimada, CantidadObjetivo = decision.NewTargetAmount, UnidadMetrica = decision.NewMetricUnit, Estado = EstadoAccion.Activa, SerieAccionId = current.SerieAccionId, Version = current.Version + 1, VigenteDesde = decision.FechaVigencia, VersionAnteriorId = current.Id, MotivoCambio = decision.Motivo, RevisionOrigenId = review.Id }; db.AccionesPlanificadas.Add(next); } } var newValues = next is null ? (decision.Tipo == TipoAjuste.Mantener ? old : $"Estado: {decision.Tipo}") : Describe(next); var adjustment = new AjustePlan { RevisionKaizenId = review.Id, AccionPlanificadaId = current.Id, NuevaAccionPlanificada = next, Tipo = decision.Tipo, Descripcion = DecisionLabel(decision.Tipo), FechaVigencia = decision.FechaVigencia, FechaReanudacion = decision.FechaReanudacion, ValoresAnteriores = old, ValoresNuevos = newValues, Motivo = decision.Motivo }; db.AjustesPlan.Add(adjustment); db.EventosHistorialMeta.Add(new() { MetaId = goal.Id, AccionPlanificada = current, RevisionKaizen = review, Tipo = HistoryType(decision.Tipo), Descripcion = $"{DecisionLabel(decision.Tipo)}: {current.Nombre}.", ValoresAnteriores = old, ValoresNuevos = newValues, Motivo = decision.Motivo }); }
        goal.FechaProximaRevision = review.FechaProximaRevision; db.EventosHistorialMeta.Add(new() { MetaId = goal.Id, RevisionKaizen = review, Tipo = TipoEventoHistorialMeta.Revision, Descripcion = $"Revisión Kaizen del {vm.InicioPeriodo:dd/MM/yyyy} al {vm.FinPeriodo:dd/MM/yyyy}: {vm.PorcentajeCumplimiento}% ({vm.Completed} de {vm.Planned})." }); await db.SaveChangesAsync(ct); var today = DateOnly.FromDateTime(DateTime.Today); await schedule.EnsureGoalScheduledAsync(goal.Id, today, today.AddDays(ScheduleService.MaximumHorizonDays), ct); await tx.CommitAsync(ct); return review.Id;
    }
    public static string Describe(AccionPlanificada x) => $"Frecuencia: {FrequencyLabel(x.Frecuencia)}; días: {x.DiasSemana ?? "-"}; cantidad: {(x.CantidadObjetivo?.ToString() ?? "-")} {x.UnidadMetrica}; horario: {(x.Hora?.ToString("HH:mm") ?? "-")}; final: {(x.FechaFin?.ToString("dd/MM/yyyy") ?? "sin fecha")}";
    private static string FrequencyLabel(FrecuenciaAccion value) => value switch { FrecuenciaAccion.Diaria => "Diaria", FrecuenciaAccion.DiasSeleccionados => "Días seleccionados", FrecuenciaAccion.Semanal => "Semanal", _ => "Fecha específica" };
    public static string DecisionLabel(TipoAjuste x) => x switch { TipoAjuste.Mantener => "Acción mantenida", TipoAjuste.Simplificar => "Acción simplificada", TipoAjuste.Aumentar => "Acción aumentada", TipoAjuste.Pausar => "Acción pausada", TipoAjuste.Reemplazar => "Acción reemplazada", _ => "Acción completada" };
    private static TipoEventoHistorialMeta HistoryType(TipoAjuste x) => x switch { TipoAjuste.Mantener => TipoEventoHistorialMeta.AccionMantenida, TipoAjuste.Simplificar => TipoEventoHistorialMeta.AccionSimplificada, TipoAjuste.Aumentar => TipoEventoHistorialMeta.AccionAumentada, TipoAjuste.Pausar => TipoEventoHistorialMeta.AccionPausada, TipoAjuste.Reemplazar => TipoEventoHistorialMeta.AccionReemplazada, _ => TipoEventoHistorialMeta.AccionCompletada };
}
